!function(){"use strict";(window.AppComponentsReady||Promise.resolve()).then(async function(){var e=getRouteName();try{var t=[];try{t=await loadCdnExperiments()}catch(e){console.warn("CDN unavailable while opening simulation:",e)}experiments=TempWorkspace.merge(t).map(migrateExperiment);var n=experiments.find(function(t){return String(t.name).toLowerCase()===String(e).toLowerCase()});if(!n)throw new Error("Experiment not found in the CDN configuration or temporary workspace.");experiments=[n],document.getElementById("simulation_id").value=n.id,document.getElementById("detail_title").textContent=n.name,document.getElementById("breadcrumb_name").textContent=n.name,document.getElementById("detail_status").textContent=(TempWorkspace.isTemp(n)?"TEMP · ":"")+n.status[0].toUpperCase()+n.status.slice(1),document.getElementById("detail_status").className="status "+(TempWorkspace.isTemp(n)?"temp":n.status),document.getElementById("saved_version").textContent=(TempWorkspace.isTemp(n)?"TEMP workspace":"Published CDN configuration")+" · v"+normalizeVersion(n.version),document.getElementById("back_configuration_link").href="/configuration/"+encodeURIComponent(n.name),document.getElementById("simulation_view").classList.remove("hidden"),renderSimulationContext()}catch(e){document.querySelector("main").innerHTML='<div class="error">Unable to load experiment: '+escapeHtml(e.message)+'</div><a class="btn" href="/">Back to dashboard</a>'}})}();